using System;using System.Diagnostics;using System.IO;using System.Net;using System.Text;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace TreeMaterialLab {
    static class LocalServiceProtocol {
        const string Prefix="Tree Material Lab Desktop: ";
        public static ProcessStartInfo StartInfo(string root,string token){return new ProcessStartInfo{FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe"),Arguments="-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+Path.Combine(root,"server.ps1")+"\" -Port 0 -OwnerToken "+token,WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardError=true,RedirectStandardOutput=true};}
        public static string ParseAddress(string line){if(line==null||!line.StartsWith(Prefix,StringComparison.Ordinal))return null;Uri uri;if(!Uri.TryCreate(line.Substring(Prefix.Length),UriKind.Absolute,out uri)||uri.Scheme!="http"||uri.Host!="127.0.0.1"||uri.Port<1024||uri.AbsolutePath!="/")return null;return uri.GetLeftPart(UriPartial.Authority)+"/";}
        static string Read(string address){var request=(HttpWebRequest)WebRequest.Create(address);request.Timeout=3000;using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream(),Encoding.UTF8))return reader.ReadToEnd();}
        static string FileHash(string file){using(var algorithm=System.Security.Cryptography.SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(algorithm.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
        public static void Verify(string root){var json=new JavaScriptSerializer();string executableSHA256=FileHash(Path.Combine(root,"树材质工坊.exe")),serverSHA256=FileHash(Path.Combine(root,"server.mjs"));Directory.CreateDirectory(Path.Combine(root,".runtime"));File.WriteAllText(Path.Combine(root,".runtime","service-check.json"),json.Serialize(new {ok=false,state="running",windowsOpened=false,executableSHA256=executableSHA256,serverSHA256=serverSHA256}),new UTF8Encoding(false));string token=Guid.NewGuid().ToString("N"),address=null;bool stopped=false;using(var job=new OwnedProcessJob())using(var process=Process.Start(StartInfo(root,token))){job.Attach(process);try{var line=Task.Run(()=>process.StandardOutput.ReadLine());if(!line.Wait(10000))throw new Exception("Service startup output timeout");address=ParseAddress(line.Result);if(address==null)throw new Exception("Invalid service startup address: "+(line.Result??"<no stdout>")+(process.HasExited?"; stderr: "+process.StandardError.ReadToEnd():""));var health=json.DeserializeObject(Read(address+"api/health")) as System.Collections.Generic.Dictionary<string,object>;if(health==null||Convert.ToString(health["product"])!="tree-material-lab")throw new Exception("Unexpected local API");if(Convert.ToString(health["version"])!=typeof(LocalServiceProtocol).Assembly.GetName().Version.ToString(2))throw new Exception("Desktop and service version mismatch");if(!Read(address).Contains("workbench.js"))throw new Exception("Missing packaged workbench");}finally{if(address!=null)try{var request=(HttpWebRequest)WebRequest.Create(address+"api/shutdown");request.Method="POST";request.Headers["X-Tree-Material-Owner"]=token;request.ContentLength=0;request.Timeout=500;using(request.GetResponse()){} }catch{}if(!process.WaitForExit(2000)){job.Dispose();process.WaitForExit(2000);}stopped=process.HasExited;}}
            if(!stopped)throw new Exception("Local service did not stop");Directory.CreateDirectory(Path.Combine(root,".runtime"));File.WriteAllText(Path.Combine(root,".runtime","service-check.json"),json.Serialize(new {ok=true,windowsOpened=false,scope="packaged Node API and HTML route; no UI automation",address=address,stopped=stopped,executableSHA256=executableSHA256,serverSHA256=serverSHA256}),new UTF8Encoding(false));
        }
    }
}
